import unittest
class RecordTests(unittest.TestCase):
    def test_unknown_owner(self):
        record = {"task": "Review draft", "owner": None}
        self.assertIsNone(record["owner"])

if __name__ == "__main__":
    unittest.main()

def extract(note, transport):
    response = transport({"input": note})
    return response["record"]

fake = lambda request: {"record": {"task": request["input"]}}
assert extract("Review draft", fake)["task"] == "Review draft"
